WITH with_windows AS (SELECT id, category, brand, price, stock_qty, launch_date, supplier_id, ROW_NUMBER() OVER (PARTITION BY category ORDER BY price DESC, id) AS row_seq, CORR(stock_qty, price) OVER w_ordered AS corr_stock_qty_price FROM products WHERE product_name IS NOT NULL WINDOW w_ordered AS (PARTITION BY category)) SELECT s.id, s.price, s.stock_qty, s.supplier_id, s.corr_stock_qty_price, (SELECT SUM(p2.price) FROM products p2 WHERE p2.supplier_id = s.supplier_id) AS sum_product_price FROM with_windows s
